<?php declare(strict_types=1);namespace App\Models;final class User extends Model{public function findByEmail(string $email):?array{return $this->db->fetch('select * from users where email=?',[$email]);}public function find(int $id):?array{return $this->db->fetch('select * from users where id=?',[$id]);}public function create(array $d):int{$this->db->execute('insert into users(name,email,password_hash,role,email_verified_at,credits) values(?,?,?,?,null,?)',[$d['name'],$d['email'],password_hash($d['password'],PASSWORD_DEFAULT),'free_user',5]);return (int)$this->db->id();}public function paginate(int $limit=20,int $offset=0):array{return $this->db->all('select id,name,email,role,credits,created_at from users order by id desc limit ? offset ?',[$limit,$offset]);}}
